import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_hist = [h[0] for h in history]
    opp_hist = [h[1] for h in history]

    opp_c = 0
    for x in opp_hist:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    my_last = my_hist[-1]
    opp_last = opp_hist[-1]

    # Detect chronic defector: defect always
    if opp_d >= n - 1 and n >= 4:
        return 'D'

    # Detect pure cooperator: exploit occasionally but keep cooperation dominant
    if opp_d == 0:
        # Near the end, grab extra value
        if n >= 92:
            if n % 3 == 0:
                return 'D'
            return 'C'
        if n % 7 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Recent window analysis
    win = history[-8:] if n >= 8 else history
    w = len(win)
    ropp_c = 0
    for _, o in win:
        if o == 'C':
            ropp_c += 1
    ropp_d = w - ropp_c
    ropp_rate = ropp_c / w if w else 1.0

    # Opponent cooperating a lot overall -> mostly cooperate
    opp_rate = opp_c / n

    if opp_rate >= 0.9:
        if n >= 90 and rng.random() < 0.5:
            return 'D'
        return 'C'

    if opp_rate <= 0.2:
        # Occasionally probe to see if they will cooperate
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Mutual defection break: if we've been in mutual D streak, try C to reset
    if n >= 3:
        if my_hist[-1] == 'D' and opp_hist[-1] == 'D' and my_hist[-2] == 'D' and opp_hist[-2] == 'D':
            if rng.random() < 0.75:
                return 'C'

    # Endgame exploitation against non-chronic defectors
    if n >= 96 and opp_rate > 0.5:
        return 'D'

    # Tit-for-tat with forgiveness, guided by recent rates
    if opp_last == 'D':
        # Forgive if the opponent's recent rate is high (isolated defection)
        if ropp_rate >= 0.7 and rng.random() < 0.6:
            return 'C'
        # If we defected last and they still defected, alternate
        if my_last == 'D' and rng.random() < 0.25:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated
        if my_last == 'D':
            # Return to cooperation
            return 'C'
        # If recent window is fully cooperative, mostly cooperate
        if ropp_d == 0:
            if n >= 85 and rng.random() < 0.3:
                return 'D'
            return 'C'
        # Mild probing when recent is strongly cooperative
        if ropp_rate >= 0.75 and rng.random() < 0.08:
            return 'D'
        return 'C'
    return 'C'
